func renderJSON(w io.Writer, r diff.Result) error {
	type fileOut struct {
		Path    string `json:"path"`
		Status  string `json:"status"`
		Adds    int    `json:"adds"`
		Dels    int    `json:"dels"`
		Unified string `json:"unified"`
	}
	type semOut struct {
		Kind   string `json:"kind"`
		Name   string `json:"name"`
		Status string `json:"status"`
		Detail string `json:"detail,omitempty"`
	}
	type payload struct {
		Files    []fileOut `json:"files"`
		Semantic []semOut  `json:"semantic,omitempty"`
	}
	out := payload{Files: make([]fileOut, 0, len(r.Files))}
	for _, fd := range r.Files {
		out.Files = append(out.Files, fileOut{Path: fd.Path, Status: fd.Status.String(), Adds: fd.Adds, Dels: fd.Dels, Unified: fd.Unified})
	}
	for _, c := range r.Semantic {
		out.Semantic = append(out.Semantic, semOut{Kind: c.Kind, Name: c.Name, Status: c.Status.String(), Detail: c.Detail})
	}
	return json.NewEncoder(w).Encode(out)
}
```

