16	func fakeCrowTwoVersions(t *testing.T) *httptest.Server {
17		t.Helper()
18		mkTgz := func(files map[string]string) []byte {
19			var buf bytes.Buffer
20			gz := gzip.NewWriter(&buf)
21			tw := tar.NewWriter(gz)
22			for n, b := range files {
23				_ = tw.WriteHeader(&tar.Header{Name: n, Mode: 0o644, Size: int64(len(b)), Typeflag: tar.TypeReg})
24				_, _ = tw.Write([]byte(b))
25			}
26			_ = tw.Close()
27			_ = gz.Close()
28			return buf.Bytes()
29		}
30		v1 := mkTgz(map[string]string{"main.tf": "resource \"aws_s3_bucket\" \"alpha\" {}\n"})
31		v2 := mkTgz(map[string]string{
32			"main.tf":      "resource \"aws_s3_bucket\" \"beta\" {}\n",
33			"variables.tf": "variable \"name\" { type = string }\n",
34		})
35	
36		mux := http.NewServeMux()
37		blob := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
38			switch r.URL.Path {
39			case "/blob/1.0.0":
40				_, _ = w.Write(v1)
41			case "/blob/1.1.0":
42				_, _ = w.Write(v2)
43			default:
44				http.NotFound(w, r)
45			}
46		}))
47		t.Cleanup(blob.Close)
48		mux.HandleFunc("/v1/modules/iac/comply/aws/", func(w http.ResponseWriter, r *http.Request) {
49			parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/v1/modules/iac/comply/aws/"), "/")
50			if len(parts) != 2 || parts[1] != "download" {
51				http.NotFound(w, r)
52				return
53			}
54			w.Header().Set("X-Terraform-Get", blob.URL+"/blob/"+parts[0])
55			w.WriteHeader(http.StatusNoContent)
56		})
57		srv := httptest.NewServer(mux)
58		t.Cleanup(srv.Close)
59		return srv
60	}
